import asyncio


async def gather_limited(factories, limit: int, timeout: float | None = None) -> list:
    if limit < 1:
        raise ValueError("limit must be >= 1")

    n = len(factories)
    if n == 0:
        return []

    results = [None] * n
    first_exception = None
    first_exception_time = float('inf')
    active_tasks = {}  # index -> task
    error_occurred = False

    loop = asyncio.get_event_loop()

    async def run_task(index, factory):
        nonlocal first_exception, first_exception_time, error_occurred
        try:
            coro = factory()
            if timeout is not None:
                result = await asyncio.wait_for(coro, timeout)
            else:
                result = await coro
            results[index] = result
        except asyncio.CancelledError:
            raise
        except Exception as e:
            now = loop.time()
            if now < first_exception_time:
                first_exception_time = now
                first_exception = e
            error_occurred = True

    try:
        next_index = 0
        while next_index < n or active_tasks:
            # Start new tasks up to limit (only if no error has occurred)
            while next_index < n and len(active_tasks) < limit and not error_occurred:
                idx = next_index
                next_index += 1
                task = asyncio.create_task(run_task(idx, factories[idx]))
                active_tasks[idx] = task

            if not active_tasks:
                break

            # Wait for at least one task to complete
            done_set, _ = await asyncio.wait(
                set(active_tasks.values()),
                return_when=asyncio.FIRST_COMPLETED,
            )

            for task in done_set:
                # Find which index this task corresponds to
                idx = None
                for i, t in active_tasks.items():
                    if t is task:
                        idx = i
                        break
                if idx is not None:
                    del active_tasks[idx]

            # If an error occurred, cancel all remaining active tasks
            if error_occurred and active_tasks:
                for task in active_tasks.values():
                    task.cancel()
                # Wait for cancelled tasks to finish their cleanup
                if active_tasks:
                    await asyncio.wait(set(active_tasks.values()))
                active_tasks.clear()
                break

    except asyncio.CancelledError:
        # gather_limited itself was cancelled — cancel all running tasks, wait, re-raise
        if active_tasks:
            for task in active_tasks.values():
                task.cancel()
            await asyncio.wait(set(active_tasks.values()))
            active_tasks.clear()
        raise

    if first_exception is not None:
        raise first_exception

    return results
