from typing import Any


def _deep_copy(value: Any) -> Any:
    if isinstance(value, dict):
        return {k: _deep_copy(v) for k, v in value.items()}
    elif isinstance(value, list):
        return [_deep_copy(item) for item in value]
    else:
        return value


def merge(base: dict, *overrides: dict) -> dict:
    result = _deep_copy(base)

    for override in overrides:
        result = _merge_layer(result, override)

    return result


def _merge_layer(current: dict, override: dict) -> dict:
    # Start with a deep copy of current to avoid mutation
    merged = _deep_copy(current)

    for key, value in override.items():
        if key.endswith('+'):
            base_key = key[:-1]
            if not isinstance(value, list):
                raise TypeError(f"Append key '{key}' requires a list value, got {type(value).__name__}")

            # Deep copy the items being appended
            items_to_append = _deep_copy(value)

            if base_key in merged:
                existing = merged[base_key]
                if not isinstance(existing, list):
                    raise TypeError(f"Cannot append to non-list value for key '{base_key}'")
                merged[base_key] = existing + items_to_append
            else:
                merged[base_key] = items_to_append
        elif value is None:
            # Delete the key if it exists
            merged.pop(key, None)
        elif isinstance(value, dict):
            if key in merged and isinstance(merged[key], dict):
                # Recursively merge the dicts
                merged[key] = _merge_layer(merged[key], value)
            else:
                # Override with deep copy of the new dict
                merged[key] = _deep_copy(value)
        else:
            # Any other value replaces the base value (deep copy for safety)
            merged[key] = _deep_copy(value)

    return merged
