            operand = self.parse_power()
            return ('unary', '!', operand)
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.peek()[0] == '^':
            self.advance()
            exponent = self.parse_unary()  # allows unary ops in exponent
            return ('binop', '^', base, exponent)
        return base

    def parse_atom(self):
        tok = self.peek()
        if tok[0] == 'INT':
            self.advance()
            return ('num', tok[1])
        if tok[0] == 'FLOAT':
            self.advance()
            return ('num', tok[1])
        if tok[0] == 'IDENT':
            name = tok[1]
            self.advance()
            if self.peek()[0] == '(':
                # function call
                self.advance()  # consume '('
                args = []
                if self.peek()[0] != ')':
                    while True:
                        args.append(self.parse_conditional())
                        if self.match_type(','):
                            continue
                        else:
                            break
                self.expect_type(')')
                return ('call', name, args)
            else:
                # variable lookup
                return ('var', name)
        if tok[0] == '(':
            self.advance()
            val = self.parse_conditional()
            self.expect_type(')')
            return val
        self.error(f"unexpected token {tok}")


def _eval_node(node, env: dict[str, float]):
    kind = node[0]

    if kind == 'num':
        return node[1]

    if kind == 'var':
        name = node[1]
        if name in env:
            return env[name]
        raise NameError(f"unknown variable '{name}'")

    if kind == 'call':
        _, name, args_nodes = node
        # Evaluate arguments
        args = [_eval_node(a, env) for a in args_nodes]
        if name == 'min':
            return min(args)
        elif name == 'max':
            return max(args)
        elif name == 'abs':
            if len(args) != 1:
                raise SyntaxError("abs takes exactly 1 argument")
            return abs(args[0])
        else:
            raise NameError(f"unknown function '{name}'")

    if kind == 'unary':
        _, op, operand_node = node
        val = _eval_node(operand_node, env)
        if op == '-':
            return -val
        elif op == '+':
            return +val
        elif op == '!':
            return 1 if val == 0 else 0
        raise SyntaxError(f"unknown unary operator '{op}'")

    if kind == 'binop':
        _, op, left_node, right_node = node

        # Short-circuit for && and ||
        if op == '&&':
            left_val = _eval_node(left_node, env)
            if left_val == 0:
                return 0
            right_val = _eval_node(right_node, env)
            return 1 if right_val != 0 else 0

        if op == '||':
            left_val = _eval_node(left_node, env)
            if left_val != 0:
                return 1
            right_val = _eval_node(right_node, env)
            return 1 if right_val != 0 else 0

        # Evaluate both sides for other binary ops
        left_val = _eval_node(left_node, env)
        right_val = _eval_node(right_node, env)

        if op == '+':
            return left_val + right_val
        elif op == '-':
            return left_val - right_val
        elif op == '*':
            return left_val * right_val
        elif op == '/':
            if right_val == 0:
                raise ZeroDivisionError("division by zero")
            # / on two ints gives int when it divides exactly, else float
            if isinstance(left_val, int) and isinstance(right_val, int):
                if left_val % right_val == 0:
                    return left_val // right_val
                else:
                    return left_val / right_val
            else:
                return left_val / right_val
        elif op == '%':
            if right_val == 0:
                raise ZeroDivisionError("modulo by zero")
            # Python's % semantics
            return left_val % right_val
        elif op == '^':
            # Power
            if isinstance(left_val, int) and isinstance(right_val, int) and right_val >= 0:
                return left_val ** right_val
            else:
                return float(left_val) ** float(right_val)
        elif op == '==':
            return 1 if left_val == right_val else 0
        elif op == '!=':
            return 1 if left_val != right_val else 0
        elif op == '<':
            return 1 if left_val < right_val else 0
        elif op == '<=':
            return 1 if left_val <= right_val else 0
        elif op == '>':
            return 1 if left_val > right_val else 0
        elif op == '>=':
            return 1 if left_val >= right_val else 0
        else:
            raise SyntaxError(f"unknown binary operator '{op}'")

    if kind == 'cond':
        _, cond_node, then_node, else_node = node
        cond_val = _eval_node(cond_node, env)
        if cond_val != 0:
            return _eval_node(then_node, env)
        else:
            return _eval_node(else_node, env)

    raise SyntaxError(f"unknown AST node type '{kind}'")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    lexer = _Lexer(expr)
    tokens = lexer.tokenize()
    parser = _Parser(tokens)
    ast_node = parser.parse()
    return _eval_node(ast_node, env or {})
