def route(grid: list[str]) -> tuple[int, str] | None:
    # Validate grid
    if not grid:
        raise ValueError("Empty grid")

    rows = len(grid)
    cols = len(grid[0])

    for i, row in enumerate(grid):
        if len(row) != cols:
            raise ValueError(f"Ragged row at index {i}")

    # Check characters and count S/E/letters
    s_count = 0
    e_count = 0
    letter_counts = {}
    pad_positions = {}  # letter -> list of positions

    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                s_count += 1
                start_pos = (r, c)
            elif ch == 'E':
                e_count += 1
                end_pos = (r, c)
            elif ch == '#':
                pass
            elif ch == '.':
                pass
            elif ch.isdigit() and '1' <= ch <= '9':
                pass
            elif 'a' <= ch <= 'z':
                letter_counts[ch] = letter_counts.get(ch, 0) + 1
                if ch not in pad_positions:
                    pad_positions[ch] = []
                pad_positions[ch].append((r, c))
            else:
                raise ValueError(f"Unknown character '{ch}' at position ({r}, {c})")

    if s_count != 1:
        raise ValueError(f"Expected exactly one 'S', found {s_count}")
    if e_count != 1:
        raise ValueError(f"Expected exactly one 'E', found {e_count}")

    for ch, count in letter_counts.items():
        if count == 1 or count > 2:
            raise ValueError(f"Letter '{ch}' appears {count} times, expected 0 or 2")

    # Determine cost of each cell
    def cell_cost(r, c):
        ch = grid[r][c]
        if ch == 'S' or ch == 'E':
            return 1
        elif ch == '.':
            return 1
        elif ch.isdigit():
            return int(ch)
        elif 'a' <= ch <= 'z':
            return 1
        else:
            # Should not reach here due to validation
            raise ValueError(f"Unexpected character '{ch}'")

    # Precompute pad mapping: for each position, if it's a pad, where does T go?
    # teleport_target[r][c] = (r2, c2) or None
    teleport_target = {}
    for ch, positions in pad_positions.items():
        if len(positions) == 2:
            p1, p2 = positions
            teleport_target[p1] = p2
            teleport_target[p2] = p1

    # BFS/Dijkstra on state (r, c), tracking cost and path
    # We want cheapest total cost, then lexicographically smallest moves string
    # Alphabet order: D < L < R < T < U

    # Moves in lex order: D, L, R, T, U
    move_order = ['D', 'L', 'R', 'T', 'U']

    # For each move direction, define delta and whether it's a teleport
    # D: (1, 0), L: (0, -1), R: (0, 1), U: (-1, 0)
    # T: teleport to other pad

    def get_neighbors(r, c):
        """Yield (move_char, nr, nc, cost_to_move) in lex order."""
        results = []

        # D
        nr, nc = r + 1, c
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            cost = cell_cost(nr, nc)
            results.append(('D', nr, nc, cost))

        # L
        nr, nc = r, c - 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            cost = cell_cost(nr, nc)
            results.append(('L', nr, nc, cost))

        # R
        nr, nc = r, c + 1
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            cost = cell_cost(nr, nc)
            results.append(('R', nr, nc, cost))

        # T (teleport) - only if current position is a pad
        if (r, c) in teleport_target:
            tr, tc = teleport_target[(r, c)]
            # Teleport costs 2 to jump to the other pad
            results.append(('T', tr, tc, 2))

        # U
        nr, nc = r - 1, c
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#':
            cost = cell_cost(nr, nc)
            results.append(('U', nr, nc, cost))

        return results

    # Dijkstra's algorithm with path tracking
    # dist[r][c] = minimum cost to reach (r, c)
    # best_path[r][c] = lexicographically smallest move string for the minimum cost

    import heapq

    INF = float('inf')
    dist = [[INF] * cols for _ in range(rows)]
    best_path = [['' for _ in range(cols)] for _ in range(rows)]

    start_r, start_c = start_pos
    end_r, end_c = end_pos

    # Priority queue: (cost, path_string, r, c)
    # We use a heap. Since we want lex smallest path among equal costs,
    # we can store (cost, path) and compare tuples. Python compares strings lex.

    dist[start_r][start_c] = 0
    best_path[start_r][start_c] = ''

    pq = [(0, '', start_r, start_c)]

    while pq:
        cost, path, r, c = heapq.heappop(pq)

        # If we've found a better or equal cost with lex smaller path already recorded, skip
        if cost > dist[r][c]:
            continue
        if cost == dist[r][c] and path > best_path[r][c]:
            continue

        # Check if we reached end
        if r == end_r and c == end_c:
            return (cost, path)

        for move_char, nr, nc, move_cost in get_neighbors(r, c):
            new_cost = cost + move_cost
            new_path = path + move_char

            # Only consider if this is better than what we have
            if new_cost < dist[nr][nc]:
                dist[nr][nc] = new_cost
                best_path[nr][nc] = new_path
                heapq.heappush(pq, (new_cost, new_path, nr, nc))
            elif new_cost == dist[nr][nc] and new_path < best_path[nr][nc]:
                # Same cost but lex smaller path
                best_path[nr][nc] = new_path
                heapq.heappush(pq, (new_cost, new_path, nr, nc))

    return None
