import re


def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()
    sections: dict[str, dict[str, str]] = {}
    current_section = ""
    last_entry_key = None  # (section, key) of the last entry in current section

    i = 0
    n = len(lines)

    while i < n:
        line = lines[i]
        stripped = line.strip()

        # Blank line
        if not stripped:
            last_entry_key = None
            i += 1
            continue

        # Comment line (starts with # or ; after optional whitespace)
        if stripped.startswith('#') or stripped.startswith(';'):
            last_entry_key = None
            i += 1
            continue

        # Section header
        if stripped.startswith('['):
            if not stripped.endswith(']'):
                raise ValueError(f"line {i + 1}: unclosed section header")
            name = stripped[1:-1].strip()
            current_section = name
            if current_section not in sections:
                sections[current_section] = {}
            last_entry_key = None
            i += 1
            continue

        # Continuation line: starts with whitespace and follows an entry
        if line[0] in (' ', '\t'):
            if last_entry_key is None:
                raise ValueError(f"line {i + 1}: continuation line with no preceding entry")
            cont_value = stripped
            section_name, key = last_entry_key
            old_value = sections[section_name][key]
            new_value = old_value + "\n" + cont_value
            sections[section_name][key] = new_value
            i += 1
            continue

        # Regular entry: key = value or key: value
        sep_idx = -1
        for j, ch in enumerate(line):
            if ch == '=' or ch == ':':
                sep_idx = j
                break

        if sep_idx == -1:
            raise ValueError(f"line {i + 1}: missing separator")

        key_part = line[:sep_idx].strip().lower()
        value_part = line[sep_idx + 1:]

        value = _parse_value(value_part, i + 1)

        if current_section not in sections:
            sections[current_section] = {}

        sections[current_section][key_part] = value
        last_entry_key = (current_section, key_part)
        i += 1

    # Interpolation
    _resolve_interpolation(sections)

    return sections


def _parse_value(value_str: str, line_num: int) -> str:
    stripped = value_str.strip()

    if not stripped:
        return ""

    if stripped[0] == '"':
        # Find the closing quote, handling escaped quotes \"
        in_quotes = True
        result = []
        j = 1
        found_close = False
        while j < len(stripped):
            ch = stripped[j]
            if ch == '\\' and j + 1 < len(stripped) and stripped[j + 1] == '"':
                result.append('"')
                j += 2
                continue
            elif ch == '"':
                found_close = True
                j += 1
                break
            else:
                result.append(ch)
                j += 1

        if not found_close:
            raise ValueError(f"line {line_num}: unterminated quote")

        # Check what's after the closing quote - should only be whitespace or inline comment
        rest = stripped[j:].strip()
        if rest and not (rest.startswith('#') or rest.startswith(';')):
            pass

        return ''.join(result)
    else:
        # Not quoted - find inline comment ( ; or # with whitespace before)
        i = 0
        while i < len(stripped):
            ch = stripped[i]
            if ch == ' ' and i + 1 < len(stripped) and stripped[i + 1] in ('#', ';'):
                return stripped[:i].strip()
            i += 1

        return stripped.strip()


def _resolve_interpolation(sections: dict[str, dict[str, str]]):
    resolved_cache: dict[tuple[str, str], str] = {}

    def resolve(section: str, key: str, stack: tuple = ()) -> str:
        cache_key = (section, key)
        if cache_key in resolved_cache:
            return resolved_cache[cache_key]

        # Check for cycle
        if cache_key in stack:
            raise ValueError("reference cycle detected")

        if section not in sections or key not in sections[section]:
            raise ValueError(f"undefined reference ${{{section}:{key}}}")

        raw_value = sections[section][key]

        result = []
        i = 0
        n = len(raw_value)

        while i < n:
            ch = raw_value[i]
            if ch == '$':
                if i + 1 < n and raw_value[i + 1] == '$':
                    result.append('$')
                    i += 2
                    continue
                elif i + 1 < n and raw_value[i + 1] == '{':
                    end = raw_value.find('}', i + 2)
                    if end == -1:
                        raise ValueError(f"unterminated reference in value for {section}.{key}")

                    ref_content = raw_value[i + 2:end]

                    if ':' in ref_content:
                        ref_section, ref_key = ref_content.split(':', 1)
                        ref_section = ref_section.strip()
                        ref_key = ref_key.strip().lower()
                    else:
                        ref_section = section
                        ref_key = ref_content.strip().lower()

                    resolved_val = resolve(ref_section, ref_key, stack + (cache_key,))
                    result.append(resolved_val)
                    i = end + 1
                    continue
                else:
                    result.append('$')
                    i += 1
                    continue
            else:
                result.append(ch)
                i += 1

        final_value = ''.join(result)
        resolved_cache[cache_key] = final_value
        return final_value

    for section in sections:
        for key in sections[section]:
            resolve(section, key)
