def _parse_range(rng: str) -> List[List[Comparator]]:
    """Parse a full range string into a list of comparator sets."""
    if not isinstance(rng, str):
        raise ValueError("range must be a string")

    rng = rng.strip()
    if not rng:
        return [[]]  # Empty range matches anything? Or is it invalid? 
        # Spec says "An empty set or * matches any release." So empty range should match anything.

    # Split by ||
    sets_str = re.split(r'\s*\|\|\s*', rng)

    result = []
    for s in sets_str:
        s_stripped = s.strip()
        if not s_stripped or s_stripped == '*':
            result.append([])
        else:
            result.append(_parse_comparator_set(s_stripped))

    return result


def _version_matches_comparator(version: Version, comp: Comparator) -> bool:
    """Check if a version satisfies a single comparator."""
    op = comp.op
    v = comp.version

    if op == '=':
        return version == v
    elif op == '>':
        return version > v
    elif op == '>=':
        return version >= v
    elif op == '<':
        return version < v
    elif op == '<=':
        return version <= v
    else:
        raise ValueError(f"unknown operator in comparator: {op}")


def _set_matches_version(version: Version, comparators: List[Comparator]) -> bool:
    """Check if a version matches all comparators in a set."""
    if not comparators:
        return True  # Empty set matches any

    for comp in comparators:
        if not _version_matches_comparator(version, comp):
            return False

    # Prerelease rule: a version with a prerelease only satisfies a set if some comparator 
    # in that set has a version with the same MAJOR.MINOR.PATCH and a prerelease.
    if version.prerelease:
        # Check if any comparator has a version with same M.m.p and a prerelease
        has_matching_pre = False
        for comp in comparators:
            cv = comp.version
            if cv.major == version.major and cv.minor == version.minor and cv.patch == version.patch:
                if cv.prerelease:  # Non-empty prerelease
                    has_matching_pre = True
                    break

        if not has_matching_pre:
            return False

    return True


def satisfies(version_str: str, rng: str) -> bool:
    """Check if a version string satisfies a range string."""
    v = parse(version_str)
    sets = _parse_range(rng)

    for comparators in sets:
        if _set_matches_version(v, comparators):
            return True

    return False


