    """Return the highest version string from the list that satisfies the range."""
    if not versions:
        return None

    sets = _parse_range(rng)

    best = None
    best_version = None

    for v_str in versions:
        try:
            v = parse(v_str)
        except ValueError:
            continue

        matched = False
        for comparators in sets:
            if _set_matches_version(v, comparators):
                matched = True
                break

        if matched:
            if best is None or v > best_version:
                best = v_str
                best_version = v

    return best
