def _parse_comparator_set(set_str: str) -> List[Comparator]:
    """Parse a single comparator set (whitespace-separated comparators)."""
    set_str = set_str.strip()
    if not set_str or set_str == '*':
        return []  # Empty list means matches any release

    # Check for hyphen range: "1.2.3 - 2.3.4"
    # Hyphen ranges have the form: version - version
    # Let's check if there's a ' - ' in the string
    hyphen_match = re.search(r'\s*-\s*', set_str)
    if hyphen_match and not any(c in set_str for c in ['<', '>', '=']):
