        # Split by ' - '
        parts = set_str.split(' - ')
        if len(parts) == 2:
            lower_str = parts[0].strip()
            upper_str = parts[1].strip()

            # Parse lower bound (fills zeros for partial)
            major_l, minor_l, patch_l, has_major_l, has_minor_l, has_patch_l = _parse_partial_version(lower_str)
            if not has_major_l:
