            elif not has_patch_l:
                lower_ver = Version(major_l, minor_l, 0)
            else:
                lower_ver = Version(major_l, minor_l, patch_l)

            # Parse upper bound (partial upper bound is exclusive of the next)
            major_u, minor_u, patch_u, has_major_u, has_minor_u, has_patch_u = _parse_partial_version(upper_str)
            if not has_major_u:
                # This shouldn't happen in a valid hyphen range
                raise ValueError("invalid hyphen range upper bound")
            elif not has_minor_u:
                # 1 - 2 means >=1.0.0 <3.0.0
                upper_ver = Version(major_u + 1, 0, 0)
                op_u = '<'
            elif not has_patch_u:
                # 1.2.3 - 2.3 means >=1.2.3 <2.4.0
                upper_ver = Version(major_u, minor_u + 1, 0)
                op_u = '<'
            else:
                # 1.2.3 - 2.3.4 means >=1.2.3 <=2.3.4
                upper_ver = Version(major_u, minor_u, patch_u)
                op_u = '<='

            return [Comparator('>=', lower_ver), Comparator(op_u, upper_ver)]

    # Regular comparator set
    comparators = []
    tokens = set_str.split()

    i = 0
    while i < len(tokens):
        token = tokens[i]

        # Determine operator
        op = ''
        if token.startswith('<='):
            op = '<='
            rest = token[2:]
        elif token.startswith('>='):
            op = '>='
            rest = token[2:]
        elif token.startswith('<'):
            op = '<'
            rest = token[1:]
        elif token.startswith('>'):
            op = '>'
            rest = token[1:]
        elif token.startswith('='):
            op = '='
            rest = token[1:]
        else:
            # No operator, or the token is a version
            rest = token
            op = ''

        if not rest:
            raise ValueError(f"invalid comparator: {token}")

        # Check for tilde or caret prefix
        if rest.startswith('~'):
            comps = _expand_tilde(rest[1:])
            comparators.extend(comps)
        elif rest.startswith('^'):
            comps = _expand_caret(rest[1:])
            comparators.extend(comps)
        else:
            # Regular version (possibly partial)
            comps = _expand_comparator(op, rest)
            comparators.extend(comps)

        i += 1

    return comparators


def _parse_range(rng: str) -> List[List[Comparator]]:
    """Parse a full range string into a list of comparator sets."""
    if not isinstance(rng, str):
        raise ValueError("range must be a string")

    rng = rng.strip()
    if not rng:
        return [[]]  # Empty range matches anything? Or is it invalid? 
        # Spec says "An empty set or * matches any release." So empty range should match anything.

    # Split by ||
    sets_str = re.split(r'\s*\|\|\s*', rng)

    result = []
    for s in sets_str:
        s_stripped = s.strip()
        if not s_stripped or s_stripped == '*':
            result.append([])
        else:
            result.append(_parse_comparator_set(s_stripped))

    return result


def _version_matches_comparator(version: Version, comp: Comparator) -> bool:
    """Check if a version satisfies a single comparator."""
    op = comp.op
    v = comp.version

    if op == '=':
        return version == v
    elif op == '>':
        return version > v
    elif op == '>=':
        return version >= v
    elif op == '<':
        return version < v
    elif op == '<=':
        return version <= v
    else:
        raise ValueError(f"unknown operator in comparator: {op}")


def _set_matches_version(version: Version, comparators: List[Comparator]) -> bool:
