    # in that set has a version with the same MAJOR.MINOR.PATCH and a prerelease.
    if version.prerelease:
        # Check if any comparator has a version with same M.m.p and a prerelease
        has_matching_pre = False
        for comp in comparators:
            cv = comp.version
            if cv.major == version.major and cv.minor == version.minor and cv.patch == version.patch:
                if cv.prerelease:  # Non-empty prerelease
                    has_matching_pre = True
                    break

        if not has_matching_pre:
