            full = full "\n" line
    }
    close("/dev/stdin")

    # Parse all records
    nrecords = split_records(full, records)

    if (nrecords == 0) {
        # Check for unterminated quote in empty/whitespace input
        exit 4
    }

    # First record is header
    hdr_n = parse_record(records[1], hdr_fields)

    # Find column index
    col_idx = -1
    if (col ~ /^#[0-9]+$/) {
        idx_str = substr(col, 2)
        col_idx = idx_str + 0
        if (col_idx < 1 || col_idx > hdr_n) {
            printf "Error: column index out of range\n" > "/dev/stderr"
            exit 3
        }
    } else {
        for (i = 1; i <= hdr_n; i++) {
            if (hdr_fields[i] == col) {
                col_idx = i
                break
            }
        }
        if (col_idx == -1) {
            printf "Error: unknown column \"%s\"\n", col > "/dev/stderr"
            exit 3
        }
    }

    # Process data rows
    count = 0
    sum = 0
    min_val = 0
    max_val = 0
    has_num = 0

    for (r = 2; r <= nrecords; r++) {
        rec_text = records[r]
        nfields = parse_record(rec_text, rec_fields)

        if (col_idx <= nfields) {
            val = rec_fields[col_idx]
        } else {
            val = ""
        }

        # Check if numeric: optional sign, then digits with optional decimal part, or .digits
        if (val ~ /^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$/) {
            num = val + 0
            sum += num
            if (!has_num) {
                min_val = num
                max_val = num
                has_num = 1
            } else {
                if (num < min_val) min_val = num
                if (num > max_val) max_val = num
            }
        }

        if (summary == 0) {
            # Print value, replacing embedded newlines with literal \n
            gsub(/\n/, "\\n", val)
            print val
        } else {
            count++
        }
    }

    if (summary == 1) {
        if (!has_num) {
            printf "count=0\n"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum, min_val, max_val
        }
    }

    function split_records(text, recs,    len, i, start, in_quote, pos) {
        len = length(text)
        n = 0
        start = 1

        while (start <= len) {
            in_quote = 0
            pos = -1
            for (i = start; i <= len; i++) {
                c = substr(text, i, 1)
                if (in_quote) {
                    if (c == "\"") {
                        if (i < len && substr(text, i+1, 1) == "\"") {
                            i++
                        } else {
                            in_quote = 0
                        }
                    }
                } else {
                    if (c == "\"") {
                        in_quote = 1
                    } else if (c == "\n") {
                        pos = i
                        break
                    } else if (c == "\r" && i < len && substr(text, i+1, 1) == "\n") {
                        pos = i + 1
                        break
                    }
                }
            }

            if (pos == -1) {
                # Reached end of input
                if (in_quote) {
                    printf "Error: unterminated quote\n" > "/dev/stderr"
                    exit 4
                }
                # Last record (no trailing newline)
                n++
                recs[n] = substr(text, start, len - start + 1)
                break
            } else {
                n++
                recs[n] = substr(text, start, pos - start + 1)
                start = pos + 1
            }
        }

        return n
    }

    function parse_record(text, out_fields,    len, i, c, in_quote, field, nfields) {
        len = length(text)
        nfields = 0
        field = ""
        in_quote = 0

        for (i = 1; i <= len; i++) {
            c = substr(text, i, 1)

            if (in_quote) {
                if (c == "\"") {
                    if (i < len && substr(text, i+1, 1) == "\"") {
                        field = field "\""
                        i++
                    } else {
                        in_quote = 0
                    }
                } else {
                    field = field c
                }
            } else {
                if (c == "\"") {
                    in_quote = 1
                } else if (c == delim) {
                    nfields++
                    out_fields[nfields] = field
                    field = ""
                } else if (c == "\n" || c == "\r") {
                    break
                } else {
                    field = field c
                }
            }
        }

        nfields++
        out_fields[nfields] = field

        return nfields
    }
